const payload = $json.body ?? $json;
const key = payload.delivery?.idempotency_key ?? $json.headers?.['idempotency-key'];
if (!key) throw new Error('Missing Simple Alert Proxy idempotency key');
const seen = $getWorkflowStaticData('global');
seen.deliveryKeys ??= {};
if (seen.deliveryKeys[key]) return [{ json: { duplicate: true, idempotency_key: key } }];
seen.deliveryKeys[key] = new Date().toISOString();
return [{ json: { duplicate: false, idempotency_key: key, kind: payload.kind, event: payload.event ?? null, events: payload.events ?? [] } }];
